const icons={star:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2L12 17.3l-5.6 2.9 1.1-6.2L3 9.6l6.2-.9Z"/>',book:'<path d="M5 3h14v18H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2Zm0 14h14M8 7h7"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18m-13 4h3m3 0h2"/>',file:'<path d="M5 3h9l5 5v13H5Zm9 0v6h5m-11 5 3 3 5-5"/>',check:'<path d="m5 12 4 4L19 6"/>',arrow:'<path d="m9 5 7 7-7 7"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',shield:'<path d="m12 3 8 3v6c0 4-4 7-8 9-4-2-8-5-8-9V6Zm-4 9 3 3 5-6"/>',spark:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5Z"/>',bell:'<path d="M5 17h14l-2-3V9a5 5 0 0 0-10 0v5Zm5 3h4"/>',share:'<path d="M12 16V3m-5 5 5-5 5 5M5 13v8h14v-8"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.star}</svg>`;
const pages=['entry','track','schedule','review','success','home','task','profile'];
const titles=['Entry','Onboarding · goal','Onboarding · pace','Plan review','Confirmation','Home','Core action','Profile'];
const params=new URLSearchParams(location.search);
let screen=pages.includes(params.get('screen'))?params.get('screen'):'entry';
let theme=params.get('theme')==='dark'?'dark':'light';
let state={track:0,pace:15,reminders:false,time:'19:00',answer:-1,done:false,activated:false};
try{state={...state,...JSON.parse(localStorage.getItem('sk-demo')||'{}')}}catch{}
const save=()=>{try{localStorage.setItem('sk-demo',JSON.stringify(state))}catch{}};
const trackNames=['Конкурс грантов','Выбираю программу','Хочу разобраться'];
const steps=(n)=>`<div class="steps">${[1,2,3].map(i=>`<i class="${i<=n?'active':''}"></i>`).join('')}</div><p class="eyebrow">Шаг ${n} из 3 · ваш план</p>`;
const info=(name,text)=>`<div class="tip">${icon(name)}<span>${text}</span></div>`;
function choice(i,title,sub,name='star'){return `<button class="choice ${state.track===i?'selected':''}" data-track="${i}" aria-pressed="${state.track===i}"><span class="iconbox">${icon(name)}</span><span><b>${title}</b><span class="small">${sub}</span></span><span class="radio"></span></button>`}
function render(){
 document.body.dataset.theme=theme;document.body.dataset.screen=screen;document.body.classList.toggle('capture',params.has('capture'));
 document.getElementById('theme-toggle').textContent=theme==='light'?'Dark theme':'Light theme';
 document.getElementById('screen-select').innerHTML=pages.map((s,i)=>`<option value="${s}" ${s===screen?'selected':''}>${titles[i]}</option>`).join('');
 const main=document.getElementById('content');let content='',cta='';
 document.getElementById('back').textContent=['entry','home'].includes(screen)?'Закрыть':'‹ Назад';
 if(screen==='entry'){
 content=`<p class="eyebrow">Ваш путь к поступлению</p><div class="hero-art"><i class="orbit"></i><i class="orbit second"></i><div class="mark">SK</div><span class="floating one">${icon('check')} Один шаг за раз</span><span class="floating two">${icon('clock')} 15 минут в день</span></div><h1 class="entry-title">Большая цель.<br>Понятный первый шаг.</h1><p class="sub">Подготовка к Конкурсу грантов Сколково — в вашем темпе.</p><div class="entry-benefits"><div class="row"><span class="iconbox">${icon('file')}</span><div><b>Личный план подготовки</b><p class="small">Задачи, материалы и прогресс</p></div></div><div class="row"><span class="iconbox">${icon('bell')}</span><div><b>Важные даты под рукой</b><p class="small">Напоминания, если вы захотите</p></div></div></div><p class="disclosure">Бесплатный проект студентов. Неофициальный сервис: не связан с приёмной комиссией и не гарантирует поступление.</p>`;cta='Составить мой план';
 }else if(screen==='track'){
 content=`${steps(1)}<h1>С чего начнём?</h1><p class="sub">Выберите ближайшую цель.<br>Её можно изменить позже.</p><div class="choices">${choice(0,'Конкурс грантов','Подготовлюсь к подаче заявки','star')}${choice(1,'Выбираю программу','Сравню варианты обучения','book')}${choice(2,'Хочу разобраться','Узнаю, как устроен отбор','spark')}</div>${info('shield','Не просим телефон, резюме или документы на старте.')}<p class="disclosure">Треки — структура концепта. Условия и доступные программы проверяются по официальным источникам.</p>`;cta='Продолжить';
 }else if(screen==='schedule'){
 content=`${steps(2)}<h1>Подстроимся<br>под ваш день</h1><p class="sub">Даже короткая задача помогает двигаться вперёд.</p><div class="section-title">Время на подготовку</div><div class="row">${[10,15,25].map(t=>`<button class="choice ${state.pace===t?'selected':''}" data-pace="${t}" aria-pressed="${state.pace===t}" style="justify-content:center;min-height:54px;padding:10px"><b style="margin:0">${t} мин</b></button>`).join('')}</div><div class="card" style="margin-top:22px"><label class="switch-row"><span><b style="font-size:14px">Напоминать о задачах</b><span class="small" style="display:block;margin-top:6px">В личном чате с ботом</span></span><input class="switch" id="reminders" type="checkbox" ${state.reminders?'checked':''} aria-label="Напоминать о задачах"></label></div><label class="time-field"><span>Удобное время · Москва, UTC+3</span><input type="time" id="reminder-time" value="${state.time}" aria-label="Время напоминания"></label>${info('calendar','Дата конкурса пока не подтверждена. Добавим её после проверки официального источника.')}<p class="disclosure">Напоминания необязательны. При включении в рабочем приложении Telegram запросит разрешение на сообщения.</p>`;cta='Посмотреть мой план';
 }else if(screen==='review'){
 content=`${steps(3)}<h1>Ваш план<br>на хороший старт</h1><p class="sub">Проверьте детали. Всё можно будет изменить в профиле.</p><div class="review-list"><div class="row"><span class="iconbox">${icon('star')}</span><div><b>${trackNames[state.track]}</b><p class="small">Цель подготовки</p></div></div><div class="row"><span class="iconbox">${icon('clock')}</span><div><b>${state.pace} минут в день</b><p class="small">Одна небольшая задача за раз</p></div></div><div class="row"><span class="iconbox">${icon('bell')}</span><div><b>${state.reminders?state.time+' · по Москве':'Без напоминаний'}</b><p class="small">${state.reminders?'Настройка для будущего бота':'Включить можно позже'}</p></div></div></div><div class="price"><span><b>Доступ к плану</b><span class="small" style="display:block;margin-top:4px">Без подписки и оплаты</span></span><strong>0 ₽</strong></div><p class="disclosure">Сохраним цель и прогресс подготовки. В рабочем сервисе правила обработки данных будут доступны до активации.</p>${info('file','Первый шаг: найти конкретный пример из вашего опыта. Это займёт около 5 минут.')}`;cta='Активировать бесплатный план';
 }else if(screen==='success'){
 content=`<div class="success-art"><div class="success-ring">${icon('check')}</div></div><div class="center"><p class="eyebrow">Всё готово для начала</p><h1 class="success-title">У вас есть план.<br>Теперь — первый шаг.</h1><p class="sub">Большая подготовка начинается<br>с маленькой задачи.</p></div><div class="card next-card"><div class="row between"><span class="tag">Первая задача</span><span class="small">5 минут</span></div><h3>Что делает ваш опыт ценным?</h3><p class="small">Разберём один пример и найдём опору для мотивационного эссе.</p></div><div class="success-meta">${icon('check')} План активирован в демо</div><p class="disclosure center">Это план подготовки.<br>Заявка в Сколково ещё не подана.</p>`;cta='Начать первую задачу';
 }else if(screen==='home'){
 const count=state.done?8:7;content=`<div class="greeting"><div><p class="small">Хороший день, чтобы начать</p><h1>Маша, вы на пути</h1></div><button class="avatar" data-nav="profile" aria-label="Открыть профиль Маши">М</button></div><div class="readiness"><p>Ваш план подготовки</p><div class="number">${state.done?'50':'44'}% <span>${count} из 16 шагов</span></div><div class="progress"><div style="width:${state.done?50:44}%"></div></div><p class="small">Прогресс по чек-листу, не оценка шансов</p></div><div class="card deadline"><div class="calendar">${icon('calendar')}</div><div><p class="small" style="color:var(--orange-ink)">Ближайший дедлайн</p><b>Анкета участника</b><p class="small">Ждём подтверждения даты</p></div></div><div class="features"><button class="feature primary" data-nav="task">${icon('star')}<b>Сильные стороны</b><span class="small">Начните с вашего опыта</span></button><button class="feature" data-note="materials">${icon('book')}<b>Материалы</b><span class="small">Гайды, эссе, интервью</span></button><button class="feature" data-nav="schedule">${icon('calendar')}<b>Дедлайны</b><span class="small">Даты и напоминания</span></button><button class="feature" data-note="resume">${icon('file')}<b>Чек-лист резюме</b><span class="small">Проверить самостоятельно</span></button></div><div class="section-title">На сегодня <span>${state.pace} минут</span></div><button class="card task-mini" data-nav="task">${icon(state.done?'check':'file')}<div><b>${state.done?'Первая задача выполнена':'Найти сильный пример из опыта'}</b><p class="small">${state.done?'Можно повторить упражнение':'Короткое упражнение · 5 минут'}</p></div></button>`;cta=state.done?'Повторить упражнение':'Продолжить подготовку';
 }else if(screen==='task'){
 content=`<p class="eyebrow">Сильные стороны · первое упражнение</p><h1>Ваш опыт<br>уже имеет вес</h1><div class="tags"><span class="tag">${icon('clock')} 5 минут</span><span class="tag">Эссе</span></div><p class="sub">Конкретный пример помогает рассказать о себе яснее, чем общие качества.</p><div class="quote">«Я организовала встречу клуба: собрала команду из 4 человек и привлекла 30 участников».</div><p class="task-question">Что делает этот пример убедительным?</p><div class="task-options">${['В нём названы действие и результат','Он звучит достаточно официально','В нём много профессиональных слов'].map((s,i)=>`<button class="choice ${state.answer===i?'selected':''}" data-answer="${i}" aria-pressed="${state.answer===i}"><span>${s}</span><span class="radio"></span></button>`).join('')}</div>${info('spark','Дальше попробуйте описать свой опыт: ситуация → действие → результат.')}<div id="task-feedback" aria-live="polite"></div>`;cta='Проверить ответ';
 }else if(screen==='profile'){
 content=`<div class="profile-head"><div class="avatar">М</div><div><h1>Маша</h1><p class="sub" style="margin-top:5px">Ваш профиль подготовки</p></div></div><div class="card"><div class="settings-row"><div><b>Моя цель</b><span class="small">${trackNames[state.track]}</span></div><button class="text-button" data-nav="track">Изменить</button></div><div class="settings-row"><div><b>Мой темп</b><span class="small">${state.pace} минут в день</span></div><button class="text-button" data-nav="schedule">Изменить</button></div><div class="settings-row"><label class="switch-row" style="width:100%"><span><b>Напоминания</b><span class="small">${state.time} · Москва, UTC+3</span></span><input id="reminders" class="switch" type="checkbox" ${state.reminders?'checked':''} aria-label="Напоминания"></label></div></div><div class="section-title">Ваши данные — под контролем</div><div class="card" style="padding:2px 16px"><button class="full-button" data-note="privacy">Какие данные мы сохраняем ${icon('shield')}</button><button class="full-button" data-note="share">Рассказать другу ${icon('share')}</button><button class="full-button danger" id="delete-data">Сбросить данные демо ${icon('arrow')}</button></div><p class="disclosure">SK Fast Track — проект студентов.<br>Условия поступления уточняйте у приёмной комиссии. Пример профиля: Маша.</p><div id="profile-feedback" aria-live="polite"></div>`;cta='Вернуться к плану';
 }
 main.innerHTML=content;main.scrollTop=0;const button=document.getElementById('main-button');button.onclick=mainHandler;button.textContent=cta;button.disabled=screen==='task'&&state.answer<0;
 main.querySelectorAll('[data-nav]').forEach(el=>el.onclick=()=>navigate(el.dataset.nav));
 main.querySelectorAll('[data-track]').forEach(el=>el.onclick=()=>{state.track=+el.dataset.track;save();render()});
 main.querySelectorAll('[data-pace]').forEach(el=>el.onclick=()=>{state.pace=+el.dataset.pace;save();render()});
 main.querySelectorAll('[data-answer]').forEach(el=>el.onclick=()=>{state.answer=+el.dataset.answer;save();render()});
 const reminders=document.getElementById('reminders');if(reminders)reminders.onchange=()=>{state.reminders=reminders.checked;save()};
 const time=document.getElementById('reminder-time');if(time)time.onchange=()=>{state.time=time.value||'19:00';save()};
 const del=document.getElementById('delete-data');if(del)del.onclick=()=>{if(confirm('Сбросить только данные этого демо?'))reset()};
 main.querySelectorAll('[data-note]').forEach(el=>el.onclick=()=>note(el.dataset.note));
}
let history=[];
function navigate(next){history.push(screen);screen=next;render();document.getElementById('content').focus({preventScroll:true})}
function note(kind){const messages={materials:'Демо библиотеки: гайд по эссе, примеры кейсов и подготовка к интервью. Полные материалы — следующий этап разработки.',resume:'Чек-лист: контакты, образование, опыт с результатами, ссылки на проекты. Загрузка и ИИ-анализ резюме запланированы позже.',privacy:'Демо хранит только выбранную цель, темп, настройки и ответ в этом браузере. Данные не отправляются на сервер.',share:'В рабочем приложении здесь откроется выбор чата Telegram с публичной ссылкой. Личные данные и прогресс в ссылку не попадут.'};const old=document.querySelector('.toast');if(old)old.remove();const box=document.createElement('div');box.className='toast';box.setAttribute('role','status');box.textContent=messages[kind];document.getElementById('content').append(box);box.scrollIntoView({block:'nearest'})}
document.getElementById('main-button').onclick=()=>{
 const routes={entry:'track',track:'schedule',schedule:'review',review:'success',success:'task',home:'task',profile:'home'};
 if(screen==='review'){state.activated=true;save()}
 if(screen==='task'){
  if(state.answer===0){state.done=true;save();document.getElementById('task-feedback').innerHTML='<div class="toast">Верно: действие и измеримый результат. Шаг сохранён в демо.</div>';const b=document.getElementById('main-button');b.textContent='Вернуться к плану';b.onclick=()=>{navigate('home');restoreMain()};}
  else{document.getElementById('task-feedback').innerHTML='<div class="toast">Посмотрите на числа в примере. Они показывают результат. Попробуйте ещё раз.</div>';document.getElementById('task-feedback').scrollIntoView({block:'nearest'})}return;
 }navigate(routes[screen]||'home');
};
const mainHandler=document.getElementById('main-button').onclick;
function restoreMain(){document.getElementById('main-button').onclick=mainHandler}
document.getElementById('back').onclick=()=>{if(['entry','home'].includes(screen)){note('privacy');return}screen=history.pop()||'home';restoreMain();render()};
document.getElementById('menu').onclick=()=>{restoreMain();navigate('profile')};
document.getElementById('theme-toggle').onclick=()=>{theme=theme==='light'?'dark':'light';render()};
document.getElementById('screen-select').onchange=e=>{restoreMain();navigate(e.target.value)};
function reset(){state={track:0,pace:15,reminders:false,time:'19:00',answer:-1,done:false,activated:false};save();history=[];screen='entry';restoreMain();render()}
document.getElementById('reset').onclick=reset;
render();
